shellCommands.command:
/bin/bash -lc "mkdir -p /tmp/pulse-check && node --input-type=module <<'JS'
import {chromium} from '@playwright/test';
const browser = await chromium.launch({headless:true});
const page = await browser.newPage({viewport:{width:1440,height:1100},deviceScaleFactor:1});
page.on('pageerror', error=>console.log('PAGE ERROR:',error.message));
await page.goto('http://localhost:5179');
await page.locator('.highcharts-root').waitFor();
await page.evaluate(()=>document.fonts.ready);
await page.screenshot({path:'/tmp/pulse-check/sales.png',fullPage:true});
console.log('size',await page.evaluate(()=>({width:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight})));
await page.getByRole('tab',{name:'Мониторинг'}).click();
await page.locator('.uplot canvas').waitFor();
await page.screenshot({path:'/tmp/pulse-check/monitoring.png',fullPage:true});
console.log('monitoring rendered',await page.locator('.uplot canvas').count());
await page.setViewportSize({width:390,height:844});
await page.screenshot({path:'/tmp/pulse-check/mobile.png',fullPage:true});
console.log('mobile size',await page.evaluate(()=>({width:document.documentElement.scrollWidth,height:document.documentElement.scrollHeight})));
await browser.close();
JS"

